1	package remediation
2	
3	import (
4		"regexp"
5		"sort"
6		"strings"
7	
8		"github.com/anthnel/devdesk/internal/scan"
9	)
10	
11	// Track says how far a base image may move.
12	type Track string
13	
14	const (
15		// TrackSameLine keeps the major version: 3.18 may become 3.21, never 4.0.
16		// A major bump is the case a scan cannot vouch for — it says the CVEs are
17		// gone, not that the application still runs — so it is not the default.
18		TrackSameLine Track = "same-line"
19		// TrackNextMajor also allows the next major version that exists.
20		TrackNextMajor Track = "next-major"
21	)
22	
23	// ParseTrack reads a configured track, falling back to TrackSameLine for
24	// anything it does not know.
25	func ParseTrack(s string) Track {
26		if Track(s) == TrackNextMajor {
27			return TrackNextMajor
28		}
29		return TrackSameLine
30	}
31	
32	// Ref is an image reference, split.
33	type Ref struct {
34		// Name is the reference without its tag and digest, as it was written:
35		// "node", "gcr.io/distroless/static". A candidate is Name plus a new tag, so
36		// it reads the way the file already does.
37		Name string
38		// Registry is the host, empty for Docker Hub. Repository is the path a
39		// registry API expects, with Docker Hub's implicit "library/" added.
40		Registry   string
41		Repository string
42		Tag        string
43		Digest     string
44	}
45	
46	// ParseRef splits an image reference into its parts. It does not validate: a
47	// string that is not a reference yields a Ref that names nothing useful, and
48	// the registry says so.
49	func ParseRef(s string) Ref {
50		var r Ref
51		s = strings.TrimSpace(s)
52		if before, digest, ok := strings.Cut(s, "@"); ok {
53			s, r.Digest = before, digest
54		}
55		// A colon after the last slash is a tag; one before it is a registry port.
56		if i := strings.LastIndex(s, ":"); i > strings.LastIndex(s, "/") {
57			s, r.Tag = s[:i], s[i+1:]
58		}
59		r.Name = s
60	
61		path := s
62		if first, rest, ok := strings.Cut(s, "/"); ok &&
63			(strings.ContainsAny(first, ".:") || first == "localhost") {
64			r.Registry, path = first, rest
65		}
66		if r.Registry == "" || r.Registry == "docker.io" || r.Registry == "index.docker.io" {
67			r.Registry = ""
68			path = strings.TrimPrefix(path, "docker.io/")
69			if !strings.Contains(path, "/") {
70				path = "library/" + path
71			}
72		}
73		r.Repository = path
74		return r
75	}
76	
77	// WithTag is the reference for another tag of the same repository. The digest
78	// is dropped: it pinned the old tag's content and would name it still.
79	func (r Ref) WithTag(tag string) string { return r.Name + ":" + tag }
80	
81	var tagVersion = regexp.MustCompile(`^v?(\d+(?:\.\d+)*)(.*)$`)
82	
83	// SplitTag cuts a tag into its version and its variant: "3.20.1-alpine3.19" is
84	// version "3.20.1" and variant "alpine3.19", "20-slim" is "20" and "slim". A tag
85	// with no leading number — "latest", "bookworm" — has no version.
86	//
87	// A number the rest of the tag is glued to is not a version either: "72d32a1d" is
88	// a commit hash, and reading it as version 72 with variant "d32a1d" made the
89	// table say there was no newer tag on its line, which is not what is wrong with
90	// it. The variant has to be set off by "-" or "_", the way every real one is
91	// (alpine, slim, bookworm-slim); "3.9rc1" is a pre-release and has no version to
92	// move from either.
93	func SplitTag(tag string) (version, variant string) {
94		m := tagVersion.FindStringSubmatch(tag)
95		if m == nil || (m[2] != "" && m[2][0] != '-' && m[2][0] != '_') {
96			return "", tag
97		}
98		return m[1], strings.TrimLeft(m[2], "-_")
99	}
100	
101	func versionParts(v string) []string { return strings.Split(v, ".") }
102	
103	// Candidates are the tags a base image could move to, best first, at most max.
104	//
105	// A candidate has the same variant as the current tag ("alpine3.19" stays on
106	// alpine, "slim" stays slim), the same number of version components (a tag
107	// written "3.18" is not offered "3.21.1", which would pin what it left
108	// floating), and a strictly higher version. Under TrackSameLine it also keeps
109	// the major version; under TrackNextMajor it may take the smallest higher major
110	// that exists too.
111	//
112	// The reason is empty when there are candidates and says why not otherwise: the
113	// tag carries no version, or nothing newer exists on the line. Nothing here
114	// says a candidate is *safe* — that is what the re-scan measures.
115	func Candidates(current string, tags []string, track Track, max int) (out []string, reason string) {
116		if current == "" {
117			return nil, "the reference has no tag — it is pinned by digest or floats on latest"
118		}
119		curVersion, curVariant := SplitTag(current)
120		if curVersion == "" {
121			return nil, "the tag carries no version to move from"
122		}
123		curParts := versionParts(curVersion)
124	
125		var newer []candidate
126		seen := map[string]bool{}
127		for _, t := range tags {
128			v, variant := SplitTag(t)
129			if v == "" || variant != curVariant || len(versionParts(v)) != len(curParts) || seen[t] {
130				continue
131			}
132			if c, ok := scan.CompareVersions(v, curVersion); !ok || c <= 0 {
133				continue
134			}
135			seen[t] = true
136			newer = append(newer, candidate{t, v})
137		}
138	
139		// The major versions on offer: the current one, and for next-major the
140		// smallest higher one.
141		allowed := map[string]bool{curParts[0]: true}
142		if track == TrackNextMajor {
143			if next := nextMajor(newer, curParts[0]); next != "" {
144				allowed[next] = true
145			}
146		}
147	
148		var kept []candidate
149		for _, c := range newer {
150			if allowed[versionParts(c.version)[0]] {
151				kept = append(kept, c)
152			}
153		}
154		sort.SliceStable(kept, func(i, j int) bool {
155			c, _ := scan.CompareVersions(kept[i].version, kept[j].version)
156			return c > 0
157		})
158		for _, c := range kept {
159			if len(out) == max {
160				break
161			}
162			out = append(out, c.tag)
163		}
164		if len(out) == 0 {
165			return nil, "no newer tag of the same variant exists on this line"
166		}
167		return out, ""
168	}
169	
170	// candidate is a tag and the version it carries.
171	type candidate struct{ tag, version string }
172	
173	// nextMajor is the smallest major version above cur among cands, or "".
174	func nextMajor(cands []candidate, cur string) string {
175		best := ""
176		for _, c := range cands {
177			major := versionParts(c.version)[0]
178			if cmp, ok := scan.CompareVersions(major, cur); !ok || cmp <= 0 {
179				continue
180			}
181			if cmp, _ := scan.CompareVersions(major, best); best == "" || cmp < 0 {
182				best = major
183			}
184		}
185		return best
